'use strict';

// MODULES //

var groupContiguousLines = require( './group_contiguous_lines.js' );


// MAIN //

/**
* Processes lines of an extracted block.
*
* @private
* @param {Array<Object>} blockLines - array of line objects
* @param {string} file - file path
* @param {number} blockIndex - index of the block in the file
* @returns {Object} processed block
*
* @example
* var lines = [ { 'text': 'int x = 0;', 'line': 1 } ];
* processBlock( lines, '/path/to/file.c', 0 );
*/
function processBlock( blockLines, file, blockIndex ) {
	var topLevelBlockIsFunc;
	var annotations;
	var closeBraces;
	var braceDepth;
	var openBraces;
	var fileScope;
	var lastFnEnd;
	var includes;
	var lineObj;
	var body;
	var text;
	var i;

	includes = [];
	fileScope = [];
	body = [];
	annotations = [];
	lastFnEnd = -1;
	braceDepth = 0;
	topLevelBlockIsFunc = false;

	// Find line number of the last function or pre-function definition closing brace...

	// Note: this assumes all structs and helper functions are grouped together at the top of the snippet
	for ( i = 0; i < blockLines.length; i++ ) {
		text = blockLines[ i ].text;
		openBraces = ( text.match( /\{/g ) || [] ).length;
		closeBraces = ( text.match( /\}/g ) || [] ).length;

		if ( braceDepth === 0 && openBraces > 0 ) {
			if ( /^\s*(?:if|else|for|while|switch|do)\b/.test( text ) || /[=]\s*\{/.test( text ) ) {
				topLevelBlockIsFunc = false;
			} else {
				topLevelBlockIsFunc = true;
			}
		}

		braceDepth += openBraces;
		braceDepth -= closeBraces;

		if ( topLevelBlockIsFunc && braceDepth === 0 ) {
			lastFnEnd = blockLines[ i ].line;
			topLevelBlockIsFunc = false;
		}
	}

	// Categorize by position...
	for ( i = 0; i < blockLines.length; i++ ) {
		lineObj = blockLines[ i ];

		if ( /^\s*#include\b/.test( lineObj.text ) ) {
			includes.push( lineObj );
		} else if ( lineObj.line <= lastFnEnd ) {
			fileScope.push( lineObj );
		} else if ( /^\s*\/\/\s*returns\b/.test( lineObj.text ) ) {
			annotations.push( lineObj );
		} else {
			body.push( lineObj );
		}
	}

	return {
		'file': file,
		'blockIndex': blockIndex,
		'includes': groupContiguousLines( includes ),
		'staticHelpers': [],
		'fileScope': groupContiguousLines( fileScope ),
		'body': groupContiguousLines( body ),
		'annotations': annotations
	};
}


// EXPORTS //

module.exports = processBlock;
